inline bool loginAccount(HWND owner,const fs::path& root,json& settings,bool creating=false){if(!accountSession)accountSession=std::make_shared<AccountSession>(root);AccountDialog dialog;dialog.creating=creating;dialog.base=str(settings,"api");if(dialog.base.empty()||dialog.base=="http://1.240.182.65")dialog.base="http://1.240.182.65:8000";RECT work{};SystemParametersInfoW(SPI_GETWORKAREA,0,&work,0);dialog.scale=std::min(GetDpiForSystem()/96.f,std::min((work.right-work.left-24)/500.f,(work.bottom-work.top-48)/680.f));static bool registered=false;if(!registered){WNDCLASSW klass{};klass.hInstance=GetModuleHandle(nullptr);klass.lpszClassName=L"SnuwAccountLogin";klass.lpfnWndProc=AccountDialog::proc;klass.hCursor=LoadCursor(nullptr,IDC_ARROW);klass.hbrBackground=(HBRUSH)(COLOR_WINDOW+1);if(!RegisterClassW(&klass))throw std::runtime_error("로그인 창 준비 실패");registered=true;}RECT frame{0,0,dialog.px(500),dialog.px(680)};AdjustWindowRectEx(&frame,WS_CAPTION|WS_SYSMENU,FALSE,WS_EX_DLGMODALFRAME);int windowWidth=frame.right-frame.left,windowHeight=frame.bottom-frame.top;HWND window=CreateWindowExW(WS_EX_DLGMODALFRAME,L"SnuwAccountLogin",L"snuwcanvas · 로그인",WS_CAPTION|WS_SYSMENU, (work.left+work.right-windowWidth)/2,(work.top+work.bottom-windowHeight)/2,windowWidth,windowHeight,owner,nullptr,GetModuleHandle(nullptr),&dialog);if(!window)throw std::runtime_error("로그인 창 생성 실패");BOOL dark=TRUE;DwmSetWindowAttribute(window,20,&dark,sizeof dark);if(owner)EnableWindow(owner,FALSE);ShowWindow(window,SW_SHOW);MSG message;while(!dialog.done&&GetMessageW(&message,nullptr,0,0)>0){if(message.message==WM_KEYDOWN&&message.wParam==VK_RETURN&&(message.hwnd==dialog.email||message.hwnd==dialog.password||message.hwnd==dialog.server)){SendMessageW(window,WM_COMMAND,IDOK,0);continue;}if(!IsDialogMessageW(window,&message)){TranslateMessage(&message);DispatchMessageW(&message);}}if(owner){EnableWindow(owner,TRUE);SetForegroundWindow(owner);}if(dialog.ok){settings["api"]=dialog.base;settings["api_key"]=accountCredential;settings["content_mode"]="standard";}return dialog.ok;}
